use vstd::prelude::*;

verus! {
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) struct State {
    pub(super) term: u64,
    pub(super) role: Role,
    pub(super) vote: Option<u64>,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum Role { Follower, Candidate, Leader }
impl State {
    pub(super) fn is_leader(&self) -> (result: bool)
        ensures result == (self.role is Leader),
    { matches!(self.role, Role::Leader) }

    pub(super) fn adopt_term(&mut self, term: u64)
        ensures self.term == if term > old(self).term { term } else { old(self).term },
            term <= old(self).term ==> *self == *old(self),
            term > old(self).term ==> self.vote == None::<u64> && self.role is Follower,
    {
        if term > self.term {
            self.term = term;
            self.vote = None;
            self.role = Role::Follower;
        }
    }

    pub(super) fn campaign(&mut self, me: u64) -> (ok: bool)
        ensures ok ==> self.term == old(self).term + 1 && self.vote == Some(me) && self.role is Candidate,
            !ok ==> *self == *old(self) && self.term == u64::MAX,
    {
        if self.term == u64::MAX { return false; }
        self.term = self.term + 1;
        self.vote = Some(me);
        self.role = Role::Candidate;
        true
    }

    pub(super) fn grant_vote(&mut self, term: u64, candidate: u64, fresh: bool) -> (granted: bool)
        ensures self.term >= old(self).term,
            self.term == old(self).term && old(self).vote.is_some() ==> self.vote == old(self).vote,
            granted ==> self.term == term && self.vote == Some(candidate) && fresh,
            self.term == old(self).term || self.term == term,
    {
        self.adopt_term(term);
        if term == self.term && fresh && (self.vote.is_none() || self.vote == Some(candidate)) {
            self.vote = Some(candidate);
            true
        } else { false }
    }
}
}
impl Default for State {
    fn default() -> Self { Self { term: 0, role: Role::Follower, vote: None } }
}
use vstd::prelude::*;
verus! {
#[cfg_attr(not(verus_keep_ghost), derive(serde::Serialize, serde::Deserialize))]
#[derive(Debug, Clone)]
pub(super) struct Entry { pub(super) term: u64, pub(super) data: Vec<u8> }

pub(super) fn fresh(candidate_term: u64, candidate_index: u64, local_term: u64, local_index: u64) -> (ok: bool)
    ensures ok == (candidate_term > local_term || (candidate_term == local_term && candidate_index >= local_index)),
{
    candidate_term > local_term || (candidate_term == local_term && candidate_index >= local_index)
}

pub(super) fn append_command(log: &mut Vec<Entry>, term: u64, data: Vec<u8>)
    requires old(log).len() < usize::MAX,
    ensures log@.len() == old(log)@.len() + 1,
        log@.take(old(log)@.len() as int) == old(log)@,
        log@[old(log)@.len() as int].term == term,
        log@[old(log)@.len() as int].data@ == data@,
{
    log.push(Entry { term, data });
}

pub(super) fn truncate_suffix(log: &mut Vec<Entry>, keep: usize)
    requires keep <= old(log).len(),
    ensures log@ == old(log)@.take(keep as int),
{
    log.truncate(keep);
}
}
//! Protocol-independent finite histories. Ghost send indices are not wire fields.
use vstd::prelude::*;
verus! {
pub struct Envelope<M> { pub group: nat, pub sender: nat, pub recipient: nat, pub body: M }
pub struct Delivery<M> { pub send: nat, pub message: Envelope<M> }

pub open spec fn delivered<M>(sent: Seq<Envelope<M>>, d: Delivery<M>) -> bool {
    d.send < sent.len() && sent[d.send as int] == d.message
}

pub open spec fn exchange<M>(sent: Seq<Envelope<M>>, input: Option<Delivery<M>>,
    output: Seq<Envelope<M>>, next: Seq<Envelope<M>>) -> bool {
    (match input { Some(d) => delivered(sent, d), None => true }) && next == sent + output
}

// Adapter types, not a required executable architecture. A step may be a host
// operation, constructor, handler segment or other justified linearization.
pub struct History<S, I, O, M> {
    pub states: Seq<S>, pub inputs: Seq<I>, pub outputs: Seq<O>,
    pub sent: Seq<Seq<Envelope<M>>>,
}

pub open spec fn valid<S, I, O, M>(h: History<S, I, O, M>, initial: spec_fn(S) -> bool,
    step: spec_fn(S, I, S, O) -> bool, receive: spec_fn(I) -> Option<Delivery<M>>,
    emit: spec_fn(O) -> Seq<Envelope<M>>) -> bool {
    &&& h.states.len() == h.inputs.len() + 1
    &&& h.outputs.len() == h.inputs.len()
    &&& h.sent.len() == h.states.len()
    &&& h.sent[0] == Seq::<Envelope<M>>::empty()
    &&& initial(h.states[0])
    &&& forall|k: int| 0 <= k < h.inputs.len() ==> step(h.states[k], #[trigger] h.inputs[k], h.states[k+1], h.outputs[k])
        && exchange(h.sent[k], receive(h.inputs[k]), emit(h.outputs[k]), h.sent[k+1])
}

pub proof fn invariant_at<S, I, O, M>(h: History<S, I, O, M>, initial: spec_fn(S) -> bool,
    step: spec_fn(S, I, S, O) -> bool, receive: spec_fn(I) -> Option<Delivery<M>>,
    emit: spec_fn(O) -> Seq<Envelope<M>>, inv: spec_fn(S, Seq<Envelope<M>>) -> bool, k: int)
    requires valid(h, initial, step, receive, emit), 0 <= k < h.states.len(),
        forall|s: S| initial(s) ==> #[trigger] inv(s, Seq::empty()),
        forall|s: S, i: I, t: S, o: O, a: Seq<Envelope<M>>, b: Seq<Envelope<M>>|
            #[trigger] inv(s, a) && #[trigger] step(s, i, t, o) && #[trigger] exchange(a, receive(i), emit(o), b) ==> inv(t, b),
    ensures inv(h.states[k], h.sent[k]),
    decreases k,
{
    if k > 0 {
        invariant_at(h, initial, step, receive, emit, inv, k-1);
        assert(h.inputs.len() == h.states.len() - 1);
        assert(step(h.states[k-1], h.inputs[k-1], h.states[k], h.outputs[k-1]));
    }
}

pub open spec fn project<R, S, I, O, M>(h: History<R, I, O, M>, view: spec_fn(R) -> S) -> History<S, I, O, M> {
    History { states: Seq::new(h.states.len(), |k: int| view(h.states[k])),
        inputs: h.inputs, outputs: h.outputs, sent: h.sent }
}

// Coverage direction: every admitted executable history maps to a model history,
// preserving received inputs, actual output messages, and send provenance.
pub proof fn simulate<R, S, I, O, M>(h: History<R, I, O, M>, rinit: spec_fn(R) -> bool,
    rstep: spec_fn(R, I, R, O) -> bool, initial: spec_fn(S) -> bool,
    step: spec_fn(S, I, S, O) -> bool, receive: spec_fn(I) -> Option<Delivery<M>>,
    emit: spec_fn(O) -> Seq<Envelope<M>>, view: spec_fn(R) -> S,
    inv: spec_fn(R, Seq<Envelope<M>>) -> bool)
    requires valid(h, rinit, rstep, receive, emit),
        forall|r: R| rinit(r) ==> #[trigger] inv(r, Seq::empty()) && initial(view(r)),
        forall|r: R, i: I, t: R, o: O, a: Seq<Envelope<M>>, b: Seq<Envelope<M>>|
            #[trigger] inv(r, a) && #[trigger] rstep(r, i, t, o) && #[trigger] exchange(a, receive(i), emit(o), b)
                ==> inv(t, b) && step(view(r), i, view(t), o),
    ensures valid(project(h, view), initial, step, receive, emit),
{
    assert forall|r: R| rinit(r) implies #[trigger] inv(r, Seq::empty()) by {}
    assert forall|r: R, i: I, t: R, o: O, a: Seq<Envelope<M>>, b: Seq<Envelope<M>>|
        #[trigger] inv(r, a) && #[trigger] rstep(r, i, t, o) && #[trigger] exchange(a, receive(i), emit(o), b)
            implies inv(t, b) by {}
    invariant_at(h, rinit, rstep, receive, emit, inv, 0);
    assert(initial(view(h.states[0])));
    let p = project(h, view);
    assert forall|k: int| 0 <= k < p.inputs.len() implies step(p.states[k], #[trigger] p.inputs[k], p.states[k+1], p.outputs[k])
        && exchange(p.sent[k], receive(p.inputs[k]), emit(p.outputs[k]), p.sent[k+1]) by {
        invariant_at(h, rinit, rstep, receive, emit, inv, k);
        assert(rstep(h.states[k], h.inputs[k], h.states[k+1], h.outputs[k]));
    }
}
} // verus!
//! DRAFT independent behavioral targets. This is an observation vocabulary,
//! not a prescribed executable representation or a second protocol engine.
use vstd::prelude::*;

verus! {
pub type Group = nat;
pub type Node = nat;
pub type Term = nat;
pub type Index = nat;

pub struct Key { pub group: Group, pub node: Node }
pub struct Entry { pub term: Term, pub command: Seq<u8> }
pub struct Snapshot {
    pub through: Index,
    pub last_term: Term,
    pub bytes: Seq<u8>,
}
pub struct View {
    pub term: Term,
    pub leader: bool,
    // The logical prefix includes compacted entries. It is NOT a free witness:
    // the generated refinement must connect it to actual execution and storage.
    pub log: Seq<Entry>,
    pub snapshot: Option<Snapshot>,
}
pub enum Event {
    Silent,
    Elect { who: Key, term: Term },
    // Observe actual commit-index advancement, never future preservation.
    Commit { who: Key, term: Term, through: Index },
    Apply { who: Key, index: Index, entry: Entry },
    // Logical application of the prefix represented by an installed snapshot.
    ApplySnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
    CreateSnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
    PersistSnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
    RestoreSnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
}
pub struct History {
    // before/after each linearized action, including crash and restart.
    pub states: Seq<Map<Key, View>>,
    pub events: Seq<Event>,
}

pub open spec fn prefix(a: Seq<Entry>, b: Seq<Entry>) -> bool {
    a.len() <= b.len() && a == b.take(a.len() as int)
}
pub open spec fn at(log: Seq<Entry>, index: Index) -> Entry
    recommends 1 <= index <= log.len(),
{ log[index as int - 1] }

pub open spec fn shape(h: History) -> bool {
    h.states.len() == h.events.len() + 1
    && forall |t: int| 0 <= t < h.events.len() ==> match #[trigger] h.events[t] {
        Event::Elect { who, term } =>
            h.states[t + 1].contains_key(who)
            && h.states[t + 1][who].leader
            && h.states[t + 1][who].term == term,
        Event::Commit { who, term, through } =>
            h.states[t + 1].contains_key(who)
            && h.states[t + 1][who].term == term
            && 1 <= through <= h.states[t + 1][who].log.len(),
        Event::Apply { who: _, index, entry: _ } => index >= 1,
        _ => true,
    }
}

pub open spec fn election_safety(h: History) -> bool {
    forall |i: int, j: int| #![trigger h.events[i], h.events[j]] 0 <= i < h.events.len() && 0 <= j < h.events.len() ==>
        match (h.events[i], h.events[j]) {
            (Event::Elect { who: a, term: ta }, Event::Elect { who: b, term: tb }) =>
                a.group == b.group && ta == tb ==> a.node == b.node,
            _ => true,
        }
}

pub open spec fn leader_append_only(h: History) -> bool {
    forall |t: int, k: Key| #![trigger h.states[t][k]] 0 <= t < h.events.len()
        && h.states[t].contains_key(k) && h.states[t + 1].contains_key(k)
        && h.states[t][k].leader && h.states[t + 1][k].leader
        && h.states[t][k].term == h.states[t + 1][k].term
        ==> prefix(h.states[t][k].log, h.states[t + 1][k].log)
}

pub open spec fn log_matching(h: History) -> bool {
    // Compare represented logs across time as well as between nodes.
    forall |s: int, t: int, a: Key, b: Key, index: Index|
        #![trigger at(h.states[s][a].log, index), at(h.states[t][b].log, index)]
        0 <= s < h.states.len() && 0 <= t < h.states.len()
        && a.group == b.group && h.states[s].contains_key(a) && h.states[t].contains_key(b)
        && 1 <= index <= h.states[s][a].log.len() && index <= h.states[t][b].log.len()
        && at(h.states[s][a].log, index).term == at(h.states[t][b].log, index).term
        ==> h.states[s][a].log.take(index as int) == h.states[t][b].log.take(index as int)
}

pub open spec fn leader_completeness(h: History) -> bool {
    forall |c: int, e: int| #![trigger h.events[c], h.events[e]] 0 <= c < h.events.len() && 0 <= e < h.events.len() ==>
        match (h.events[c], h.events[e]) {
            (Event::Commit { who: a, term: tc, through }, Event::Elect { who: b, term: te }) =>
                a.group == b.group && tc < te ==>
                    h.states[e + 1].contains_key(b)
                    && through <= h.states[e + 1][b].log.len()
                    && h.states[c + 1][a].log.take(through as int)
                        == h.states[e + 1][b].log.take(through as int),
            _ => true,
        }
}

pub open spec fn applied(event: Event, group: Group, index: Index) -> Option<Entry> {
    match event {
        Event::Apply { who, index: i, entry } =>
            if who.group == group && i == index { Some(entry) } else { None },
        Event::ApplySnapshot { who, prefix, snapshot: _ } =>
            if who.group == group && 1 <= index <= prefix.len() {
                Some(at(prefix, index))
            } else { None },
        _ => None,
    }
}

pub open spec fn state_machine_safety(h: History) -> bool {
    forall |a: int, b: int, group: Group, index: Index|
        0 <= a < h.events.len() && 0 <= b < h.events.len()
        && applied(h.events[a], group, index).is_some()
        && applied(h.events[b], group, index).is_some()
        ==> applied(h.events[a], group, index) == applied(h.events[b], group, index)
}

// The application semantics is selected per group and refined to the actual
// service. Decoding recovers application state, not historical commands.
pub struct Application {
    pub initial: Seq<u8>,
    pub step: spec_fn(Seq<u8>, Entry) -> Seq<u8>,
    pub decode: spec_fn(Seq<u8>) -> Option<Seq<u8>>,
}
pub open spec fn fold(app: Application, entries: Seq<Entry>) -> Seq<u8>
    decreases entries.len(),
{
    if entries.len() == 0 { app.initial }
    else { (app.step)(fold(app, entries.drop_last()), entries.last()) }
}
pub open spec fn snapshot_represents(app: Application, snap: Snapshot, entries: Seq<Entry>) -> bool {
    snap.through == entries.len()
    && snap.last_term == (if entries.len() == 0 { 0nat } else { entries.last().term })
    && (app.decode)(snap.bytes) == Some(fold(app, entries))
}
pub open spec fn committed_prefix_before(h: History, time: int, group: Group, entries: Seq<Entry>) -> bool {
    entries.len() == 0 || exists |c: int| #![trigger h.events[c]] 0 <= c < time && match h.events[c] {
        Event::Commit { who, term: _, through } => who.group == group
            && entries.len() <= through && h.states[c + 1].contains_key(who)
            && prefix(entries, h.states[c + 1][who].log),
        _ => false,
    }
}
pub open spec fn snapshot_fidelity(h: History, apps: Map<Group, Application>) -> bool {
    (forall |t: int, k: Key| #![trigger h.states[t][k]] 0 <= t < h.states.len() && h.states[t].contains_key(k) ==>
        match h.states[t][k].snapshot {
            None => true,
            Some(s) => apps.contains_key(k.group) && s.through <= h.states[t][k].log.len()
                && snapshot_represents(apps[k.group], s, h.states[t][k].log.take(s.through as int))
                && committed_prefix_before(h, t, k.group, h.states[t][k].log.take(s.through as int)),
        })
    && (forall |t: int| 0 <= t < h.events.len() ==> match #[trigger] h.events[t] {
        Event::ApplySnapshot { who, prefix, snapshot }
        | Event::CreateSnapshot { who, prefix, snapshot }
        | Event::PersistSnapshot { who, prefix, snapshot }
        | Event::RestoreSnapshot { who, prefix, snapshot } =>
            apps.contains_key(who.group) && snapshot_represents(apps[who.group], snapshot, prefix)
                && committed_prefix_before(h, t, who.group, prefix),
        _ => true,
    })
}
} // verus!
use futures::{channel::mpsc, lock::Mutex as AsyncMutex};
use madsim::{fs, net, rand::{self, Rng}, task, time::*};
use serde::{Deserialize, Serialize};
use std::{fmt, io, net::SocketAddr, sync::{Arc, Mutex}};

#[path = "state.rs"]
mod state;
use state::{State, Role};
#[path = "log.rs"]
mod log_core;
use log_core::Entry;

#[derive(Clone)]
pub struct RaftHandle {
    pub(crate) endpoint: net::Endpoint,
    inner: Arc<Mutex<Raft>>,
    gate: Arc<AsyncMutex<()>>,
}
type MsgSender = mpsc::UnboundedSender<ApplyMsg>;
pub type MsgRecver = mpsc::UnboundedReceiver<ApplyMsg>;
pub enum ApplyMsg {
    Command { data: Vec<u8>, index: u64 },
    Snapshot { data: Vec<u8>, term: u64, index: u64 },
}
#[derive(Debug)]
pub struct Start { pub index: u64, pub term: u64 }
#[derive(thiserror::Error, Debug)]
pub enum Error {
    #[error("this node is not a leader, next leader: {0}")]
    NotLeader(usize),
    #[error("IO error")]
    IO(#[from] io::Error),
}
pub type Result<T> = std::result::Result<T, Error>;
#[derive(Debug, Clone, Serialize, Deserialize)]
struct Persist {
    generation: u64, term: u64, vote: Option<u64>,
    base: u64, base_term: u64, log: Vec<Entry>,
    #[serde(skip)]
    snapshot: Vec<u8>,
}
struct Raft {
    peers: Vec<SocketAddr>, me: usize, apply_ch: MsgSender, state: State,
    disk: Persist, slots: [u64; 2], commit: u64, applied: u64,
    deadline: Instant, heartbeat: Instant, votes: Vec<bool>, next: Vec<u64>, matched: Vec<u64>,
}
fn invalid(message: &str) -> io::Error { io::Error::new(io::ErrorKind::InvalidData, message) }
impl fmt::Debug for Raft {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { write!(f, "Raft({})", self.me) }
}
impl Raft {
    fn timeout() -> Duration { Duration::from_millis(rand::thread_rng().gen_range(350..650)) }
    fn reset(&mut self) { self.deadline = Instant::now() + Self::timeout(); }
    fn last(&self) -> u64 { self.disk.base + self.disk.log.len() as u64 }
    fn term_at(&self, index: u64) -> Option<u64> {
        if index == self.disk.base { Some(self.disk.base_term) }
        else if index > self.disk.base { self.disk.log.get((index - self.disk.base - 1) as usize).map(|e| e.term) }
        else { None }
    }
    fn apply(&mut self) {
        while self.applied < self.commit {
            self.applied += 1;
            let entry = &self.disk.log[(self.applied - self.disk.base - 1) as usize];
            let _ = self.apply_ch.unbounded_send(ApplyMsg::Command { data: entry.data.clone(), index: self.applied });
        }
    }
    fn advance_commit(&mut self) {
        let mut m = self.matched.clone();
        m[self.me] = self.last();
        m.sort_unstable();
        let index = m[(m.len() - 1) / 2];
        if index > self.commit && self.term_at(index) == Some(self.state.term) { self.commit = index; }
        self.apply();
    }
    fn become_leader(&mut self) {
        self.state.role = Role::Leader;
        let next = self.last().saturating_add(1);
        self.next.fill(next);
        self.matched.fill(0);
        self.heartbeat = Instant::now();
    }
}
impl RaftHandle {
    pub async fn new(peers: Vec<SocketAddr>, me: usize) -> (Self, MsgRecver) {
        assert!(!peers.is_empty() && me < peers.len(), "invalid fixed membership");
        let endpoint = net::Endpoint::bind(SocketAddr::from(([0, 0, 0, 0], peers[me].port()))).await.expect("bind Raft RPC");
        let (apply_ch, recver) = mpsc::unbounded();
        let n = peers.len();
        let this = Self { endpoint, gate: Arc::new(AsyncMutex::new(())), inner: Arc::new(Mutex::new(Raft {
            peers, me, apply_ch, state: State::default(),
            disk: Persist { generation: 0, term: 0, vote: None, base: 0, base_term: 0, log: vec![], snapshot: vec![] },
            slots: [0, 0], commit: 0, applied: 0,
            deadline: Instant::now() + Raft::timeout(), heartbeat: Instant::now(),
            votes: vec![false; n], next: vec![1; n], matched: vec![0; n],
        })) };
        this.restore().await.expect("failed to restore");
        this.start_rpc_server();
        let h = this.clone();
        task::spawn(async move { loop { sleep(Duration::from_millis(10)).await; h.tick().await; } });
        (this, recver)
    }
    pub fn term(&self) -> u64 { self.inner.lock().unwrap().state.term }
    pub fn is_leader(&self) -> bool { self.inner.lock().unwrap().state.is_leader() }
    pub async fn start(&self, cmd: &[u8]) -> Result<Start> {
        let _gate = self.gate.lock().await;
        let result = {
            let mut r = self.inner.lock().unwrap();
            if !r.state.is_leader() { return Err(Error::NotLeader((r.me + 1) % r.peers.len())); }
            if r.last() == u64::MAX || r.disk.log.len() == usize::MAX { return Err(invalid("log exhausted").into()); }
            let term = r.state.term;
            log_core::append_command(&mut r.disk.log, term, cmd.to_vec());
            r.heartbeat = Instant::now();
            Start { index: r.last(), term }
        };
        self.persist().await?;
        self.inner.lock().unwrap().advance_commit();
        Ok(result)
    }
    pub async fn snapshot(&self, index: u64, snapshot: &[u8]) -> Result<()> {
        let _gate = self.gate.lock().await;
        {
            let mut r = self.inner.lock().unwrap();
            if index <= r.disk.base { return Ok(()); }
            if index > r.applied { return Err(invalid("snapshot beyond applied prefix").into()); }
            let term = r.term_at(index).ok_or_else(|| invalid("snapshot boundary"))?;
            let remove = (index - r.disk.base) as usize;
            r.disk.log.drain(..remove);
            r.disk.base = index; r.disk.base_term = term; r.disk.snapshot = snapshot.to_vec();
        }
        self.persist().await?;
        Ok(())
    }
    pub async fn cond_install_snapshot(&self, term: u64, index: u64, snapshot: &[u8]) -> bool {
        let _gate = self.gate.lock().await;
        let r = self.inner.lock().unwrap();
        r.disk.base == index && r.disk.base_term == term && r.disk.snapshot == snapshot
    }
    // Two generation-matched state/snapshot pairs; replace the older pair first.
    // Recovery accepts only complete pairs. No cross-file atomicity is required.
    async fn persist(&self) -> io::Result<()> {
        let (bytes, snapshot, first, generation) = {
            let mut r = self.inner.lock().unwrap();
            r.disk.term = r.state.term; r.disk.vote = r.state.vote;
            r.disk.generation = r.disk.generation.checked_add(1).ok_or_else(|| invalid("generation exhausted"))?;
            (bincode::serialize(&r.disk).map_err(|_| invalid("encode state"))?,
                if r.disk.base == 0 { vec![] } else { bincode::serialize(&(r.disk.generation, &r.disk.snapshot)).map_err(|_| invalid("encode snapshot"))? },
                if r.slots[0] <= r.slots[1] { 0 } else { 1 }, r.disk.generation)
        };
        for slot in [first, 1 - first] {
            // Invalidate/replace the older pair first; the other pair remains recoverable.
            let snap = fs::File::create(if slot == 0 { "snapshot" } else { "snapshot.backup" }).await?;
            snap.write_all_at(&snapshot, 0).await?;
            snap.sync_all().await?;
            let file = fs::File::create(if slot == 0 { "state" } else { "state.backup" }).await?;
            file.write_all_at(&bytes, 0).await?;
            file.sync_all().await?;
            self.inner.lock().unwrap().slots[slot] = generation;
        }
        Ok(())
    }
    async fn restore(&self) -> io::Result<()> {
        let mut best: Option<Persist> = None;
        let mut exists = false;
        for (slot, name) in ["state", "state.backup"].iter().enumerate() {
            match fs::read(name).await {
                Ok(bytes) => {
                    exists = true;
                    if let Ok(mut p) = bincode::deserialize::<Persist>(&bytes) {
                        let snapshot = fs::read(if slot == 0 { "snapshot" } else { "snapshot.backup" }).await;
                        let decoded = if p.base == 0 { Some((p.generation, vec![])) }
                            else { snapshot.ok().and_then(|b| bincode::deserialize::<(u64, Vec<u8>)>(&b).ok()) };
                        match decoded {
                            Some((generation, data)) if generation == p.generation => p.snapshot = data,
                            _ => continue,
                        }
                        self.inner.lock().unwrap().slots[slot] = p.generation;
                        if best.as_ref().map_or(true, |b| p.generation > b.generation) { best = Some(p); }
                    }
                }
                Err(e) if e.kind() == io::ErrorKind::NotFound => {},
                Err(e) => return Err(e),
            }
        }
        if exists && best.is_none() { return Err(invalid("no complete durable image; refusing fresh vote")); }
        if let Some(p) = best {
            let mut r = self.inner.lock().unwrap();
            r.state.term = p.term; r.state.vote = p.vote;
            r.commit = p.base; r.applied = p.base;
            if p.base > 0 { let _ = r.apply_ch.unbounded_send(ApplyMsg::Snapshot { data: p.snapshot.clone(), term: p.base_term, index: p.base }); }
            r.disk = p;
        }
        self.persist().await
    }
    fn start_rpc_server(&self) {
        let this = self.clone();
        self.endpoint.add_rpc_handler(move |a: RequestVoteArgs| { let h = this.clone(); async move { h.request_vote(a).await.expect("vote persistence") } });
        let this = self.clone();
        self.endpoint.add_rpc_handler(move |a: AppendArgs| { let h = this.clone(); async move { h.append(a).await.expect("append persistence") } });
    }
    async fn request_vote(&self, a: RequestVoteArgs) -> io::Result<RequestVoteReply> {
        let _gate = self.gate.lock().await;
        let reply = {
            let mut r = self.inner.lock().unwrap();
            let fresh = log_core::fresh(a.last_term, a.last, r.term_at(r.last()).unwrap(), r.last());
            let valid = a.candidate < r.peers.len() as u64;
            let granted = if valid { r.state.grant_vote(a.term, a.candidate, fresh) } else { false };
            if granted { r.reset(); }
            RequestVoteReply { term: r.state.term, granted }
        };
        self.persist().await?;
        Ok(reply)
    }
    async fn append(&self, a: AppendArgs) -> io::Result<AppendReply> {
        let mut installed = false;
        let _gate = self.gate.lock().await;
        let reply = {
            let mut r = self.inner.lock().unwrap();
            let mut success = false;
            let mut hint = r.last().saturating_add(1);
            if a.leader < r.peers.len() && a.term >= r.state.term {
                r.state.adopt_term(a.term); r.state.role = Role::Follower; r.reset();
                if let Some((base, term, bytes)) = a.snapshot {
                    if base > r.commit {
                        if r.term_at(base) == Some(term) {
                            let remove = (base - r.disk.base) as usize;
                            r.disk.log.drain(..remove);
                        } else { r.disk.log.clear(); }
                        r.disk.base = base; r.disk.base_term = term; r.disk.snapshot = bytes.clone();
                        r.commit = base; r.applied = base; installed = true;
                        // Released after the durable write below.
                    }
                    success = true;
                } else if r.term_at(a.prev) == Some(a.prev_term) {
                    success = true;
                    let mut index = a.prev;
                    for entry in a.entries {
                        if index == u64::MAX { success = false; break; }
                        index += 1;
                        if r.term_at(index) != Some(entry.term) {
                            if index <= r.commit { success = false; break; }
                            let keep = (index - r.disk.base - 1) as usize;
                            log_core::truncate_suffix(&mut r.disk.log, keep);
                            r.disk.log.push(entry);
                        }
                    }
                    if success { r.commit = r.commit.max(a.commit.min(index)); }
                } else if let Some(term) = r.term_at(a.prev) {
                    hint = a.prev;
                    while hint > r.disk.base && r.term_at(hint - 1) == Some(term) { hint -= 1; }
                }
            }
            AppendReply { term: r.state.term, success, hint }
        };
        self.persist().await?;
        let mut r = self.inner.lock().unwrap();
        if installed {
            let _ = r.apply_ch.unbounded_send(ApplyMsg::Snapshot { data: r.disk.snapshot.clone(), term: r.disk.base_term, index: r.disk.base });
        }
        r.apply();
        Ok(reply)
    }
    async fn tick(&self) {
        let _gate = self.gate.lock().await;
        let election = {
            let mut r = self.inner.lock().unwrap();
            if !r.state.is_leader() && Instant::now() >= r.deadline {
                let me = r.me;
                if !r.state.campaign(me as u64) { r.reset(); return; }
                r.votes.fill(false); r.votes[me] = true; r.reset();
                let a = RequestVoteArgs { term: r.state.term, candidate: me as u64, last: r.last(), last_term: r.term_at(r.last()).unwrap() };
                if r.peers.len() == 1 { r.become_leader(); }
                Some((a, r.peers.clone(), me))
            } else { None }
        };
        if let Some((a, peers, me)) = election {
            self.persist().await.expect("campaign persistence");
            for (peer, addr) in peers.into_iter().enumerate().filter(|(i,_)| *i != me) {
                let h = self.clone(); let a = a.clone();
                task::spawn(async move {
                    if let Ok(reply) = h.endpoint.call_timeout(addr, a.clone(), Duration::from_millis(250)).await {
                        h.vote_reply(peer, a.term, reply).await;
                    }
                });
            }
        }
        let sends = {
            let mut r = self.inner.lock().unwrap();
            let mut sends = vec![];
            if r.state.is_leader() && Instant::now() >= r.heartbeat {
                r.heartbeat = Instant::now() + Duration::from_millis(80);
                for peer in 0..r.peers.len() {
                    if peer == r.me { continue; }
                    let next = r.next[peer].min(r.last().saturating_add(1));
                    let snapshot = if next <= r.disk.base { Some((r.disk.base, r.disk.base_term, r.disk.snapshot.clone())) } else { None };
                    let prev = if snapshot.is_some() { r.disk.base } else { next - 1 };
                    let entries = if snapshot.is_some() { vec![] } else { r.disk.log[(next - r.disk.base - 1) as usize..].to_vec() };
                    sends.push((peer, r.peers[peer], AppendArgs { term: r.state.term, leader: r.me, prev, prev_term: r.term_at(prev).unwrap(), entries, commit: r.commit, snapshot }));
                }
            }
            sends
        };
        for (peer, addr, a) in sends {
            let h = self.clone();
            task::spawn(async move {
                if let Ok(reply) = h.endpoint.call_timeout(addr, a.clone(), Duration::from_millis(250)).await { h.append_reply(peer, a, reply).await; }
            });
        }
    }
    async fn vote_reply(&self, peer: usize, term: u64, reply: RequestVoteReply) {
        let _gate = self.gate.lock().await;
        {
            let mut r = self.inner.lock().unwrap();
            r.state.adopt_term(reply.term);
            if r.state.term == term && r.state.role == Role::Candidate && reply.granted {
                r.votes[peer] = true;
                if r.votes.iter().filter(|v| **v).count() > r.peers.len() / 2 { r.become_leader(); }
            }
        }
        self.persist().await.expect("reply persistence");
    }
    async fn append_reply(&self, peer: usize, a: AppendArgs, reply: AppendReply) {
        let _gate = self.gate.lock().await;
        {
            let mut r = self.inner.lock().unwrap();
            r.state.adopt_term(reply.term);
            if r.state.is_leader() && r.state.term == a.term {
                if reply.success {
                    let matched = a.snapshot.as_ref().map_or(a.prev + a.entries.len() as u64, |s| s.0);
                    r.matched[peer] = r.matched[peer].max(matched);
                    r.next[peer] = r.matched[peer].saturating_add(1);
                    r.advance_commit();
                } else if r.next[peer] == a.prev.saturating_add(1) {
                    r.next[peer] = reply.hint.min(r.next[peer].saturating_sub(1)).max(1);
                    r.heartbeat = Instant::now();
                }
            }
        }
        self.persist().await.expect("reply persistence");
    }
}
#[derive(Debug, Clone, Serialize, Deserialize)]
struct RequestVoteArgs { term: u64, candidate: u64, last: u64, last_term: u64 }
#[derive(Debug, Clone, Serialize, Deserialize)]
struct RequestVoteReply { term: u64, granted: bool }
impl net::rpc::Request for RequestVoteArgs { type Response = RequestVoteReply; const ID: u64 = 1; }
#[derive(Debug, Clone, Serialize, Deserialize)]
struct AppendArgs { term: u64, leader: usize, prev: u64, prev_term: u64, entries: Vec<Entry>, commit: u64, snapshot: Option<(u64,u64,Vec<u8>)> }
#[derive(Debug, Clone, Serialize, Deserialize)]
struct AppendReply { term: u64, success: bool, hint: u64 }
impl net::rpc::Request for AppendArgs { type Response = AppendReply; const ID: u64 = 10; }

