        assert(!(a[n as int - 1] && b[n as int - 1]));
    }
}
pub proof fn majority_overlap(a: Seq<bool>, b: Seq<bool>) -> (peer: int)
    requires a.len() == b.len(), tally(a, a.len()) > a.len() / 2,
        tally(b, b.len()) > b.len() / 2,
    ensures 0 <= peer < a.len(), a[peer], b[peer],
